param([Parameter(Mandatory)][string]$DataAssemblyPath, [string]$Filter)
$ErrorActionPreference='Stop';$repositoryRoot=Split-Path $PSScriptRoot -Parent
$checkDirectory=Join-Path ([IO.Path]::GetTempPath()) ('oilgas-maintenance-client-'+[guid]::NewGuid().ToString('N'));[void](New-Item -ItemType Directory -Path $checkDirectory)
# Current full workflow client plus controlled HTTP/account/diagnostics seams; no server/provider/browser/OIDC claim.
[xml]$project='<Project Sdk="Microsoft.NET.Sdk"><PropertyGroup><TargetFramework>net10.0</TargetFramework><Nullable>enable</Nullable><ImplicitUsings>enable</ImplicitUsings><DefineConstants>WORKFLOW_INBOX_FOCUSED</DefineConstants><NoWarn>$(NoWarn);CS0436</NoWarn></PropertyGroup><ItemGroup><FrameworkReference Include="Microsoft.AspNetCore.App"/><PackageReference Include="Microsoft.NET.Test.Sdk" Version="18.4.0"/><PackageReference Include="xunit" Version="2.9.3"/><PackageReference Include="xunit.runner.visualstudio" Version="3.1.5"/><PackageReference Include="Moq" Version="4.20.72"/></ItemGroup><ItemGroup/></Project>'
$group=$project.SelectNodes('/Project/ItemGroup')[1]
$hseWorkflowTests=$project.CreateElement('Compile');$hseWorkflowTests.SetAttribute('Include',(Join-Path $repositoryRoot 'Beep.OilandGas.Web.Auth.Tests/CompanyHseWorkflowClientTests.cs'));[void]$group.AppendChild($hseWorkflowTests)
$startFixture=$project.CreateElement('Compile');$startFixture.SetAttribute('Include',(Join-Path $repositoryRoot 'Beep.OilandGas.ApiService.Tests/WorkOrderExecutionStartFixture.cs'));[void]$group.AppendChild($startFixture)
$startStateTests=$project.CreateElement('Compile');$startStateTests.SetAttribute('Include',(Join-Path $repositoryRoot 'Beep.OilandGas.Web.Auth.Tests/WorkOrderExecutionStartStateTests.cs'));[void]$group.AppendChild($startStateTests)
$startState=$project.CreateElement('Compile');$startState.SetAttribute('Include',(Join-Path $repositoryRoot 'Beep.OilandGas.Web/Services/WorkOrderExecutionStartState.cs'));[void]$group.AppendChild($startState)
foreach($source in @('Beep.OilandGas.Web/Services/WorkOrderSubmissionState.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderSubmissionStateTests.cs','Beep.OilandGas.Web/Services/WorkOrderMaterialUsageState.cs','Beep.OilandGas.Web/Services/WorkOrderLaborUsageState.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderMaterialUsageStateTests.cs')){$node=$project.CreateElement('Compile');$node.SetAttribute('Include',(Join-Path $repositoryRoot $source));[void]$group.AppendChild($node)}
$stageTests=$project.CreateElement('Compile');$stageTests.SetAttribute('Include',(Join-Path $repositoryRoot 'Beep.OilandGas.Web.Auth.Tests/MaintenanceAssignedStageClientTests.cs'));[void]$group.AppendChild($stageTests)
$inspectionTests=$project.CreateElement('Compile');$inspectionTests.SetAttribute('Include',(Join-Path $repositoryRoot 'Beep.OilandGas.Web.Auth.Tests/MaintenanceInspectionClientTests.cs'));[void]$group.AppendChild($inspectionTests)
$permitTests=$project.CreateElement('Compile');$permitTests.SetAttribute('Include',(Join-Path $repositoryRoot 'Beep.OilandGas.Web.Auth.Tests/WorkOrderExecutionPermitClientTests.cs'));[void]$group.AppendChild($permitTests)
$processRead=$project.CreateElement('Compile');$processRead.SetAttribute('Include',(Join-Path $repositoryRoot 'Beep.OilandGas.Web/Services/IRecordedProcessClient.cs'));[void]$group.AppendChild($processRead)
$receivingState=$project.CreateElement('Compile');$receivingState.SetAttribute('Include',(Join-Path $repositoryRoot 'Beep.OilandGas.Web/Services/CompanyMaintenanceReceivingState.cs'));[void]$group.AppendChild($receivingState)
$nativeInterface=$project.CreateElement('Compile');$nativeInterface.SetAttribute('Include',(Join-Path $repositoryRoot 'Beep.OilandGas.Web/Services/ICompanyMaintenanceHandoffClient.cs'));[void]$group.AppendChild($nativeInterface)
$stateSource=$project.CreateElement('Compile');$stateSource.SetAttribute('Include',(Join-Path $repositoryRoot 'Beep.OilandGas.Web/Services/CompanyMaintenanceHandoffState.cs'));[void]$group.AppendChild($stateSource)
foreach($source in @('Beep.OilandGas.Web/Services/WorkOrderExecutionPermitState.cs','Beep.OilandGas.Web/Services/WorkOrderExecutionPermitDecisionState.cs','Beep.OilandGas.Web/Services/WorkOrderExecutionPermitDecisionState.MaterialAcceptance.cs','Beep.OilandGas.Web/Services/WorkOrderExecutionPermitDecisionState.PersonnelAcceptance.cs','Beep.OilandGas.Web/Services/WorkOrderExecutionPermitDecisionState.DocumentAcceptance.cs','Beep.OilandGas.Web/Services/WorkOrderExecutionPermitDecisionState.PersonnelAssignment.cs','Beep.OilandGas.Web/Services/WorkOrderExecutionPermitDecisionState.PersonnelRelease.cs','Beep.OilandGas.Web/Services/CompanyPersonnelPolicyState.cs','Beep.OilandGas.Web/Services/CompanyPersonnelIdentityState.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderExecutionPermitStateTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderExecutionPermitApprovalClientTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderExecutionPermitDecisionClientTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderMaterialSourceTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderMaterialCatalogTests.cs','Beep.OilandGas.ApiService.Tests/WorkOrderMaterialAcceptanceFixture.cs','Beep.OilandGas.ApiService.Tests/WorkOrderCompleteApprovalFixture.cs','Beep.OilandGas.ApiService.Tests/WorkOrderPersonnelReviewFixture.cs','Beep.OilandGas.ApiService.Tests/WorkOrderPersonnelAcceptanceFixture.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderPersonnelSourceClientTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderPermitDocumentSourceClientTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderAssignedPersonnelTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderPersonnelReleaseClientTests.cs','Beep.OilandGas.Web.Auth.Tests/CompanyPersonnelPolicyClientTests.cs','Beep.OilandGas.Web.Auth.Tests/CompanyPersonnelIdentityClientTests.cs','Beep.OilandGas.Web.Auth.Tests/CompanyEmploymentEligibilityTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderAcceptedMaterialReviewTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderMaterialAcceptanceClientTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderPersonnelAcceptanceClientTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderPersonnelAcceptanceStateTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderMaterialAcceptanceStateTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderMaterialReadinessTests.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderMaterialAllocationClientTests.cs','Beep.OilandGas.Web/Services/WorkOrderMaterialAllocationState.cs','Beep.OilandGas.Web.Auth.Tests/WorkOrderMaterialAllocationStateTests.cs','Beep.OilandGas.Web/Services/IBusinessProcessServiceClient.cs','Beep.OilandGas.Web/Services/BusinessProcessServiceClient.cs','Beep.OilandGas.Web/Services/BusinessProcessServiceClient.Maintenance.cs','Beep.OilandGas.Web/Services/BusinessProcessServiceClient.ReturnAcceptance.cs','Beep.OilandGas.Web/Services/BusinessProcessServiceClient.Closure.cs','Beep.OilandGas.Web/Services/BusinessProcessServiceClient.AssetEvidence.cs','Beep.OilandGas.Web/Services/BusinessProcessServiceClient.CompletionDecision.cs','Beep.OilandGas.Web/Services/ApiClient.cs','Beep.OilandGas.Web/Services/OilGasApiException.cs','Beep.OilandGas.Client/App/CompanyClientContext.cs','Beep.OilandGas.Client/App/CompanyResponseStream.cs','Beep.OilandGas.ApiService.Tests/Fixtures/WorkflowInboxExternalBoundaries.cs','Beep.OilandGas.Web.Auth.Tests/MaintenanceHandoffClientTests.cs')){
    $node=$project.CreateElement('Compile');$node.SetAttribute('Include',(Join-Path $repositoryRoot $source));[void]$group.AppendChild($node)
}
$dependencies=Join-Path $repositoryRoot 'Beep.OilandGas.Repository.Tests/bin/company-focused/Debug/net10.0'
foreach($name in @('TheTechIdea.Data','Beep.OilandGas.Models','Beep.OilandGas.PPDM.Models','DataManagementModels')){
    $path=if($name -eq 'TheTechIdea.Data'){(Resolve-Path -LiteralPath $DataAssemblyPath).Path}else{Join-Path $dependencies ($name+'.dll')}
    $node=$project.CreateElement('Reference');$node.SetAttribute('Include',$name);$hint=$project.CreateElement('HintPath');$hint.InnerText=$path;[void]$node.AppendChild($hint)
    if($name -eq 'TheTechIdea.Data'){$alias=$project.CreateElement('Aliases');$alias.InnerText='global,actualData';[void]$node.AppendChild($alias)}
    [void]$group.AppendChild($node)
}
@'
extern alias actualData;
global using ProcessInstanceRequest = actualData::Beep.OilandGas.Models.Data.Process.ProcessInstanceRequest;
'@ | Set-Content (Join-Path $checkDirectory 'ActualContracts.cs') -Encoding utf8
$path=Join-Path $checkDirectory 'MaintenanceClient.csproj';$project.Save($path)
if($Filter -eq 'FullyQualifiedName~CompanyHseWorkflowClientTests'){
    foreach($node in @($group.SelectNodes('Compile'))){
        $name=[IO.Path]::GetFileName($node.GetAttribute('Include'))
        if($name -ne 'CompanyHseWorkflowClientTests.cs' -and $name -notmatch '^(IRecordedProcessClient|ICompanyMaintenanceHandoffClient|IBusinessProcessServiceClient|BusinessProcessServiceClient(\..+)?|ApiClient|OilGasApiException|CompanyClientContext|CompanyResponseStream|WorkflowInboxExternalBoundaries)\.cs$'){
            [void]$group.RemoveChild($node)
        }
    }
    $existing=@($group.SelectNodes('Compile') | ForEach-Object {$_.GetAttribute('Include')})
    Get-ChildItem (Join-Path $repositoryRoot 'Beep.OilandGas.Web/Services') -Filter 'BusinessProcessServiceClient.*.cs' | ForEach-Object {
        if($_.FullName -notin $existing){$node=$project.CreateElement('Compile');$node.SetAttribute('Include',$_.FullName);[void]$group.AppendChild($node)}
    }
    $project.Save($path)
}
if($Filter){dotnet test $path --filter $Filter --logger 'console;verbosity=normal'}else{dotnet test $path --logger 'console;verbosity=normal'}
if($LASTEXITCODE -ne 0){throw "Maintenance workflow client check failed: $checkDirectory"}
